 "content": "def transform(grid):
    """Shear the colored figure left by one column for every row above its base."""
    h, w = len(grid), len(grid[0])
    colored_rows = [r for r in range(h) if any(grid[r][c] != 0 for c in range(w))]
    if not colored_rows:
        return [row[:] for row in grid]
    base = max(colored_rows)
    out = [[0] * w for _ in range(h)]
    for r in range(h):
        shift = r - base
        for c in range(w):
            color = grid[r][c]
            nc = c + shift
            if color != 0 and 0 <= nc < w:
                out[r][nc] = color
    return out

